# Prominent real microphone and compact Caddie layout.
s=re.sub(r"function Caddie\(\{distance,setDistance,wind,setWind,windDir,setWindDir,elev,setElev,lie,setLie,result,units,ask,listening,heard,caddieText,recordAdvice\}\)\{.*?\}\nfunction Bag",
'''function Caddie({distance,setDistance,wind,setWind,windDir,setWindDir,elev,setElev,lie,setLie,result,units,ask,listening,heard,caddieText,recordAdvice}){return <><Title kicker="TALKING CADDIE" title="Tap and speak" sub="Distance, lie, wind, trouble or club"/><TouchableOpacity style={[s.mic,listening&&s.micLive]} onPress={ask} accessibilityLabel="Ask Caddie microphone"><Text style={s.micIcon}>🎙</Text><Text style={s.micTitle}>{listening?'LISTENING…':'ASK CADDIE'}</Text></TouchableOpacity><Text style={s.heard}>{heard}</Text><View style={s.panel}><Text style={s.answerLabel}>CADDIE SAYS</Text><Text style={s.answer}>{caddieText}</Text><View style={s.recRow}><Text style={s.bigClub}>{result.club}</Text><Text style={s.cardSub}>Playing {result.y} {units==='METRES'?'m':'yd'}</Text></View></View><Field label={`DISTANCE · ${units==='METRES'?'METRES':'YARDS'}`} value={distance} onChangeText={setDistance} keyboardType="numeric"/><Seg items={LIES} value={lie} setValue={setLie}/><Field label={`WIND · ${units==='METRES'?'km/h':'mph'}`} value={wind} onChangeText={setWind} keyboardType="numeric"/><Seg items={WIND} value={windDir} setValue={setWindDir}/><Field label="ELEVATION %" value={elev} onChangeText={setElev} keyboardType="numeric"/><Btn text="GET ADVICE" onPress={()=>{Tts.stop().catch(()=>{});Tts.speak(caddieText)}}/><Btn text="SAVE CADDIE NOTE TO HOLE" onPress={recordAdvice} outline/></>}
function Bag''', s, count=1, flags=re.S)

# Compact My Bag with direct number entry.
s=re.sub(r"function Bag\(\{bag,setBag,units\}\)\{.*?\}\nfunction Course",
'''function Bag({bag,setBag,units}){const names=bag.map(x=>x[0]),add=name=>{if(!names.includes(name))setBag([...bag,[name,name==='Putter'?0:100]])},del=name=>setBag(bag.filter(x=>x[0]!==name)),change=(i,d)=>setBag(bag.map((x,k)=>k===i?[x[0],Math.max(0,x[1]+d)]:x)),exact=(i,v)=>setBag(bag.map((x,k)=>k===i?[x[0],Math.max(0,units==='METRES'?n(v):n(v)/1.09361)]:x));return <><Title kicker="MY BAG" title="14-Club Setup" sub="Saved distances power Practice and Caddie"/><View style={s.panel}><Text style={s.panelTitle}>ADD CLUB</Text><View style={s.chips}>{CLUB_LIBRARY.filter(x=>!names.includes(x)).map(x=><TouchableOpacity key={x} style={s.chip} onPress={()=>add(x)}><Text style={s.chipText}>+ {x}</Text></TouchableOpacity>)}</View></View>{bag.map((x,i)=><View style={s.bagRow} key={x[0]}><View style={s.bagName}><Text style={s.cardTitle}>{x[0]}</Text></View><TextInput style={s.bagInput} value={String(yd(x[1],units))} onChangeText={v=>exact(i,v)} keyboardType="numeric"/><Text style={s.unitMini}>{units==='METRES'?'m':'yd'}</Text><TouchableOpacity style={s.step} onPress={()=>change(i,-1)}><Text style={s.stepText}>−</Text></TouchableOpacity><TouchableOpacity style={s.step} onPress={()=>change(i,1)}><Text style={s.stepText}>+</Text></TouchableOpacity><TouchableOpacity onPress={()=>del(x[0])}><Text style={s.remove}>REMOVE</Text></TouchableOpacity></View>)}</>}
function Course''', s, count=1, flags=re.S)

# More is the compact toolbox.
